class Solution {
  public List<List<Integer>> aggregateTimeSeries(int[][] series1, int[][] series2) {
    List<List<Integer>> res = new ArrayList<>();
    int i = 0, j = 0, n = series1.length, m = series2.length;
    while (i < n || j < m) {
      int t;
      if (i < n && j < m) t = Math.min(series1[i][0], series2[j][0]);
      else if (i < n) t = series1[i][0];
      else t = series2[j][0];
      while (i < n && series1[i][0] < t) i++;
      while (j < m && series2[j][0] < t) j++;
      long v1 = i < n ? series1[i][1] : 0, v2 = j < m ? series2[j][1] : 0;
      res.add(java.util.Arrays.asList(t, (int) (v1 + v2)));
      if (i < n && series1[i][0] == t) i++;
      if (j < m && series2[j][0] == t) j++;
    }
    return res;
  }
}
